CREATE TABLE IF NOT EXISTS papers(id VARCHAR(100) PRIMARY KEY,subject_code VARCHAR(32) NOT NULL,status VARCHAR(20) NOT NULL,metadata_json LONGTEXT NOT NULL,created_at VARCHAR(40) NOT NULL,updated_at VARCHAR(40) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS questions(paper_id VARCHAR(100) NOT NULL,id VARCHAR(100) NOT NULL,seq INT NOT NULL,data_json LONGTEXT NOT NULL,PRIMARY KEY(paper_id,id),FOREIGN KEY(paper_id) REFERENCES papers(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS attempts(id VARCHAR(100) PRIMARY KEY,paper_id VARCHAR(100) NOT NULL,student_name VARCHAR(200) NOT NULL,started_at VARCHAR(40) NOT NULL,deadline VARCHAR(40) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'active',submitted_at VARCHAR(40),snapshot_json LONGTEXT NOT NULL,answers_json LONGTEXT NOT NULL,flags_json LONGTEXT NOT NULL,grades_json LONGTEXT NOT NULL,released TINYINT NOT NULL DEFAULT 0,owner_hash VARCHAR(64) NOT NULL DEFAULT '',INDEX idx_attempts_status(status),FOREIGN KEY(paper_id) REFERENCES papers(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS jobs(id VARCHAR(100) PRIMARY KEY,type VARCHAR(20) NOT NULL,target_id VARCHAR(100) NOT NULL,status VARCHAR(20) NOT NULL,progress INT NOT NULL DEFAULT 0,message TEXT NOT NULL,result_json LONGTEXT NOT NULL,error TEXT NOT NULL,created_at VARCHAR(40) NOT NULL,updated_at VARCHAR(40) NOT NULL,payload_json LONGTEXT NOT NULL,INDEX idx_jobs_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS grade_history(id BIGINT PRIMARY KEY AUTO_INCREMENT,attempt_id VARCHAR(100) NOT NULL,question_id VARCHAR(100) NOT NULL,grade_json LONGTEXT NOT NULL,created_at VARCHAR(40) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS settings(`key` VARCHAR(100) PRIMARY KEY,value LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS admin_sessions(token_hash VARCHAR(64) PRIMARY KEY,expires BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS login_failures(client VARCHAR(64) NOT NULL,created BIGINT NOT NULL,INDEX idx_failures_created(created)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS paper_scans(id VARCHAR(100) PRIMARY KEY,paper_title TEXT NOT NULL,student_name VARCHAR(200) NOT NULL,status VARCHAR(20) NOT NULL,snapshot_json LONGTEXT NOT NULL,recognized_json LONGTEXT NOT NULL,attempt_id VARCHAR(100) NOT NULL,created_at VARCHAR(40) NOT NULL,INDEX idx_scan_attempt(attempt_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS scan_pages(id VARCHAR(100) PRIMARY KEY,scan_id VARCHAR(100) NOT NULL,seq INT NOT NULL,name TEXT NOT NULL,data_url LONGTEXT NOT NULL,FOREIGN KEY(scan_id) REFERENCES paper_scans(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
